-- ScholarBridgeAi — Scholarship rewrite pass 35 (Spain)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- Spain has a structural fact that shapes all four rows: the regional and ministry grant systems
-- are built for Spanish and EU nationals, and the international-specific scholarship at a Madrid
-- university is repeatedly restricted to Latin American graduates. UAB is retired on that basis.
-- Values are in EUR where published; amount_usd_value stays 0 for non-USD awards.

-- 539 Universitat Autonoma de Barcelona — retired: no international scholarship, and the UAB's own
-- FAQ states that the ministry grants require a residence permit, not a student permit
UPDATE scholarships SET
  title = 'Universitat Autonoma de Barcelona - no international scholarship; ministry grants need a residence permit (retired)',
  description = 'The UAB states the position more honestly than most Spanish universities and it is worth quoting because it decides the whole question. Its FAQ for international students says that all students enrolled in Spanish universities can apply for the general grant or the mobility grant offered by the Ministry of Education, but that students from non-EU countries must hold a residence permit, not a student permit, to apply for them, and that special grants for foreign students must be applied for in their home country. A student from Uzbekistan on a study visa therefore cannot use the Spanish ministry grant system, and the UAB does not operate an international scholarship of its own to replace it. What the university does offer is an enrolment grant for some programmes, the possibility of collaborating in university areas under a student grant, the Santander Excelencia 360 degree scholarship whose 2025-26 round ran from 3 February to 7 May 2026, the #UABRefugi aid for students in situations of refuge, an equity grant, and language-course grants - plus a mobility budget that pays UAB students to go abroad rather than paying foreign students to come. The old record claimed a USD 2,250 Autonomous University of Barcelona Scholarship with a January to May deadline; no such award is published, so the row is withdrawn rather than repriced.',
  coverage_type = 'Unspecified', award_basis = 'variable', award_amount = NULL, award_currency = 'EUR', amount_usd_value = 0,
  deadline = 'Not published', deadline_date = NULL, deadline_type = 'not_published',
  website_url = 'https://www.uab.cat/web/mobility-international-exchange/mobility-international-exchange-programmes/faqs-para-estudiantes-internacionales-1345672012135.html',
  source_url = 'https://www.uab.cat/web/mobility-international-exchange/mobility-international-exchange-programmes/faqs-para-estudiantes-internacionales-1345672012135.html',
  verification_status = 'verified', source_reliability = 8, is_active = false,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Retired after reading the UAB own pages on 2026-10-25: the FAQ for international students at uab.cat states that non-EU students must have a residence permit, not a student permit, to apply for the ministry grants and that special grants for foreign students must be applied for in the home country; the UAB grant search engine page lists the actual calls, which are the Santander Excelencia 360 degree scholarship (3 February to 7 May 2026), the #UABRefugi aid for degree, master and doctoral studies, the equity grant, language-course grants and the international mobility call that funds UAB students going abroad at EUR 1,200 for a full year, 750 for a semester and 500 for stays of three months or less. The former row claimed a USD 2,250 scholarship with a January to May deadline and all three degree levels. No international scholarship is published, so nothing was repriced and the row is deactivated; the FAQ is kept as the source so the reasoning can be checked.'
WHERE id = 539;

-- 540 Universidad Autonoma de Madrid — the excellence scholarship for official master's study
UPDATE scholarships SET
  title = 'UAM Becas de Excelencia para Master Oficial',
  description = 'This is the award a strong applicant should actually aim at in Madrid, and the detail that decides everything is that it reimburses rather than funds: the UAM opens 45 Becas de Excelencia for students with an outstanding record who are already enrolled and paid in an official UAM master''s degree for the year in question, and then returns 100% of the first-enrolment public fees - the rates the Community of Madrid sets for national students - up to a maximum of 60 ECTS. The application window for 2026-27 ran from 25 March to 15 September 2026. The academic bar is published by branch: an average of 8.70 out of 10 in Arts and Humanities, Sciences, Health Sciences and Social and Legal Sciences, and 7.30 in Engineering and Architecture. The 45 places are distributed by branch as well - 8 in Arts and Humanities, 9 in Sciences, 5 in Health Sciences, 18 in Social and Legal Sciences and 5 in Engineering and Architecture - which makes Social and Legal Sciences the least crowded route. The scholarship cannot be combined with any other tuition aid financed by UAM master''s funds or with another scholarship from any institution that covers the same tuition. Two neighbouring schemes are closed to an applicant from Uzbekistan: the UAM international student page lists master''s programmes reserved for Latin American and Filipino public officials, and the UAM Fondo Social requires Spanish or European Union nationality.',
  requirements = 'Hold a completed degree or equivalent with an outstanding grade average, at least 8.70 out of 10 in Arts and Humanities, Sciences, Health Sciences or Social and Legal Sciences, or at least 7.30 in Engineering and Architecture. Be enrolled in and have paid for a new-entry place in an official UAM master''s degree for the 2026-27 academic year before the application deadline, since the award reimburses a fee you have already paid rather than funding one you have not. Apply through the UAM electronic seat between 25 March and 15 September 2026. Hold no other tuition aid financed by UAM master''s funds and no other scholarship from another institution that covers the same tuition. Note that the Fondo Social grants require Spanish or European Union nationality and that the UAM international programmes listed on its international page are for Latin American and Filipino public officials.',
  coverage_type = 'Partial Tuition', award_basis = 'fixed', award_amount = NULL, award_currency = 'EUR', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition reimbursement',
  tuition_coverage = 'A refund of 100% of the first-enrolment public fees for an official UAM master''s degree, capped at 60 ECTS and calculated at the Community of Madrid rate for national students. It does not cover living costs and it arrives after the student has already paid the fee.',
  english_requirements = 'The scholarship sets no separate English score; the language requirement of the chosen master''s programme applies, and many UAM master''s degrees are taught in Spanish.',
  required_documents = '["UAM official master''s enrolment and fee payment receipt","Degree certificate and academic transcript showing the average grade","Electronic application through the UAM seat","Declaration of any other scholarships or tuition aid held","Identity document and NIE where available"]',
  deadline = '25 March to 15 September 2026 for the 2026-27 call',
  deadline_date = '2026-09-15', deadline_type = 'fixed', application_status = 'closed',
  website_url = 'https://www.uam.es/uam/estudios/beca-ayuda/uam-propias/becas-excelencia-master-26-27',
  source_url = 'https://www.uam.es/uam/estudios/beca-ayuda/uam-propias/becas-excelencia-master-26-27',
  application_url = 'https://sede.uam.es/sede/becaExcelenciaMasterUAM',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the UAM own page fetched 2026-10-25 (uam.es/uam/estudios/beca-ayuda/uam-propias/becas-excelencia-master-26-27), which states that 45 scholarships are offered to students with an outstanding record who have enrolled in an official UAM master''s degree for 2026-27 by the closing date, that the window runs from 25 March to 15 September 2026, that the award is a refund of 100% of the first-enrolment public fees set by the Community of Madrid for national students up to 60 ECTS, that it is incompatible with any other UAM-financed master''s tuition aid or any other institution''s tuition scholarship, that candidates must have formalised and paid the enrolment, and that the minimum average is 8.70 out of 10 in Arts and Humanities, Sciences, Health Sciences and Social and Legal Sciences and 7.30 in Engineering and Architecture, with 8, 9, 5, 18 and 5 places respectively. The UAM international students page was also read the same day: its scholarship listing opens a general window of 12 January to 2 March 2026 and its programmes include a master''s in behavioural and health sciences methodology and a Ramon Areces molecular biomedicine master''s, plus programmes reserved for Latin American and Filipino public officials. The UAM Fondo Social PDF states that applicants must hold Spanish or European Union nationality. CORRECTIONS: the row was titled Autonomous University of Madrid Scholarships, carried an invented USD 2,250, claimed all three degree levels and gave a January to May deadline. There is no general UAM scholarship of that size open to a student from Uzbekistan; the real instrument is a post-enrolment reimbursement at master''s level, and the record now says so, including the awkward fact that the money arrives after the fee is paid. award_amount is NULL because the value is a variable percentage of a fee rather than a published sum.'
WHERE id = 540;

-- 558 Universidad Complutense de Madrid — the matricula aids, with the AUIP restriction stated
UPDATE scholarships SET
  title = 'UCM Matricula Aids for Grado and Master',
  description = 'The Complutense runs several aid lines and the one a non-EU applicant can use is the matricula aid, which reduces rather than removes the fee. The Ayudas UCM de Matricula for 2025-26 cover 100%, 75% or 50% of the amount a student pays for the credits enrolled in first and second enrolment, with a master''s ceiling of EUR 2,100 and, for a degree, a ceiling equal to the public second-enrolment price for a full year. The application window ran from 25 February to 10 March 2026 through the UCM scholarship portal. Applicants must be enrolled in an official degree or master''s programme at a UCM centre, and the award is decided by competitive ranking against family income and academic record. The dedicated international award at the same university points the other way and is worth naming so nobody plans around the wrong page: the UCM international master''s scholarships, which exempt 100%, 75% or 50% of tuition for up to 60 credits across up to 15 places, are open only to non-Spanish graduates of Latin American universities associated with the Ibero-American Postgraduate University Association, so an applicant from Uzbekistan is not eligible for them. The UCM also runs an Excellence line for master''s study and collaboration grants for applicants who were refused the ministry scholarship.',
  requirements = 'Be enrolled in an official degree or master''s programme at a UCM centre for the academic year of the call, in first or second enrolment. Apply through the UCM scholarship portal at becas.ucm.es within the published window, which for 2025-26 was 25 February to 10 March 2026. Provide the family income and academic documentation the call requires, since the award is ranked competitively on need and record. Note that the international master''s scholarships at UCM are restricted to non-Spanish graduates of AUIP Latin American universities and are not open to applicants from Uzbekistan; the matricula aid is the route that is. The master''s ceiling is EUR 2,100 and the degree ceiling is the public second-enrolment price for a full year.',
  coverage_type = 'Partial Tuition', award_basis = 'range', award_amount = 2100, award_currency = 'EUR', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Need-based tuition aid',
  tuition_coverage = 'Between 50% and 100% of the amount payable for the credits enrolled, capped at EUR 2,100 for a master''s degree and at the public second-enrolment price of a full year for a degree. It reduces tuition and covers no living costs.',
  english_requirements = 'The aid sets no separate English score; the language requirement of the chosen programme applies, and most UCM degrees are taught in Spanish.',
  required_documents = '["UCM enrolment receipt for the academic year","Application through the becas.ucm.es portal","Family income documentation","Academic transcript","Identity document or NIE"]',
  deadline = '25 February to 10 March 2026 for the 2025-26 call',
  deadline_date = '2026-03-10', deadline_type = 'fixed', application_status = 'closed',
  website_url = 'https://www.ucm.es/ayudas-ucm-de-matricula-para-grado-y-master',
  source_url = 'https://www.ucm.es/ayudas-ucm-de-matricula-para-grado-y-master',
  application_url = 'https://becas.ucm.es/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two UCM own pages read on 2026-10-25: ucm.es/ayudas-ucm-de-matricula-para-grado-y-master states that the Ayudas UCM de Matricula for 2025-26 cover 100%, 75% or 50% of the amount payable for credits in first and second enrolment, that the master''s aid cannot exceed EUR 2,100 and the degree aid cannot exceed the public second-enrolment price for a full year, that the window ran from 25 February to 10 March 2026, and that applications go through the becas.ucm.es portal; ucm.es/latinas describes the UCM international scholarships for Latin America and the Caribbean as exempting 100%, 75% or 50% of master''s tuition for up to 60 credits and restricts them to non-Spanish graduates of Latin American universities associated with AUIP. The UCM master''s page also lists an Excellence line for master''s study and a collaboration grant line. CORRECTIONS: the row was titled Complutense University Scholarships, carried an invented USD 3,375, claimed all three degree levels and gave a January to May deadline. The usable instrument for a non-EU applicant is a capped tuition aid of up to EUR 2,100 at master''s level or a full-year second-enrolment cap at degree level, and the record now states plainly that the headline international master''s scholarships at UCM are Latin-America-only. amount_usd_value is 0 because the provider publishes in euros and award_amount carries the published EUR 2,100 master''s ceiling.'
WHERE id = 558;

-- 696 Universidad Carlos III de Madrid — the graduate school tuition calls, which are open to any admitted master's applicant
UPDATE scholarships SET
  title = 'UC3M School of Graduate Studies Master''s Tuition Scholarships',
  description = 'Carlos III runs its master''s funding as a series of numbered calls rather than one scheme, and the important point for an applicant from outside the European Union is that the general call does not restrict nationality - it asks only that you are a new student who meets the access requirements and that you have lodged the master''s admission application with the access fee paid before the deadline. The general call AM01 for 2026-27 took applications from 1 December 2025 to 31 May 2026, with partial decisions from 23 February 2026 for applications submitted by 31 January, from 27 April 2026 for those submitted between 1 February and 31 March, and the final decision from 22 June 2026 for applications submitted between 1 April and 31 May. The documentation is a motivation letter that may set out the applicant''s economic and personal situation, plus a declaration of any scholarships already held. Separate calls cover particular programmes, such as AM02 for the master''s in legal practice and AM03 which ran from 14 March to 31 May 2026. The university publishes the percentage of tuition covered and the study grant attached to each call inside the call document rather than on the summary page, so no figure is claimed here. Two other Madrid schemes are closed to an applicant from Uzbekistan and are worth knowing about: the Community of Madrid excellence scholarships of EUR 2,100 require having sat the university access examination in Madrid or having studied Bachillerato there, and the AUIP master''s scholarships are for Latin American graduates. The International Foundation Program, a one-year preparatory route for students who completed secondary school outside the European Union, does offer two scholarships of about EUR 8,200 each.',
  requirements = 'Be a new student who holds, or is in a position to obtain before the deadline, the access requirements for official master''s study under Royal Decree 822/2021. Lodge the UC3M master''s admission application in the university application system and pay the access application fee before the closing date of the call, which for the general call AM01-26/27 was 31 May 2026. Submit the scholarship application within the call window, which opened on 1 December 2025, attaching a signed motivation letter that may describe your economic and personal situation and a declaration of any financial aid or scholarships obtained in previous studies. Note that the Community of Madrid excellence scholarship requires a Madrid access examination or Bachillerato and that the AUIP scholarships are restricted to Latin American graduates, so neither applies to an applicant from Uzbekistan.',
  coverage_type = 'Partial Tuition', award_basis = 'range', award_amount = NULL, award_currency = 'EUR', award_period = 'year',
  degree_levels = '["Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based and need-aware tuition scholarship',
  tuition_coverage = 'Each call covers a percentage of University Master''s tuition fees, sometimes with an additional study grant, and UC3M publishes the percentage and the grant inside the call document rather than on the summary page. No published figure is claimed here. Tuition only.',
  english_requirements = 'The scholarships set no separate English score; the language requirement of the chosen master''s programme applies, and UC3M offers programmes in both Spanish and English.',
  required_documents = '["UC3M master''s admission application with the access fee paid","Signed motivation letter","Declaration of other scholarships or financial aid held","Degree certificate and transcript","Application through the UC3M aid portal before the call deadline"]',
  deadline = '31 May 2026 for the general call AM01-26/27, which opened on 1 December 2025',
  deadline_date = '2026-05-31', deadline_type = 'fixed', application_status = 'closed',
  website_url = 'https://www.uc3m.es/postgraduate/scholarships/main/2026',
  source_url = 'https://www.uc3m.es/postgraduate/scholarships/main/2026',
  application_url = 'https://www.uc3m.es/postgraduate/aid/main/how-to-apply',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from three UC3M own pages read on 2026-10-25: uc3m.es/postgraduate/scholarships/main/2026 lists the 2026-27 calls for University Master''s tuition fees, gives the general call AM01-26/27 an application period of 1 December 2025 to 31 May 2026 with partial decisions from 23 February 2026 for applications to 31 January, from 27 April 2026 for 1 February to 31 March and a final decision from 22 June 2026 for 1 April to 31 May, sets the requirements as new students holding the access requirements under Royal Decree 822/2021 who have formalised the master''s admission application with the access fee paid before 31 May 2026, lists the documentation as a signed motivation letter and a declaration of other aid, and records call AM02 for the master''s in legal practice and AM03 with a 14 March to 31 May 2026 window; the UC3M international foundation programme page describes the one-year, 60 ECTS preparatory route at EUR 8,500; the UC3M Becas de Excelencia de la Comunidad de Madrid page gives the EUR 2,100 value, the 9 to 29 January 2026 window, the 2,551 scholarships and the requirement to have sat the access examination in Madrid or studied Bachillerato in the region; the AUIP master''s scholarship page restricts that call to Latin American graduates of AUIP universities. CORRECTIONS: the row was titled UC3M Scholarships for International Students, carried an invented USD 3,125, claimed all three degree levels and gave a January to May deadline. The real instrument is a set of master''s tuition calls that do not restrict nationality, the value sits in the call PDFs, and the Madrid regional scholarship that looks like the headline award is closed to applicants from outside Spain. award_amount is NULL rather than a guessed percentage of a fee.'
WHERE id = 696;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = v.avail, funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = v.tuition, covers_living_expenses = false, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (148, 'Universitat Autonoma de Barcelona - no international scholarship; ministry grants need a residence permit', 'No', 'Not applicable', 'None published for international students', false, 'The UAB FAQ states that non-EU students need a residence permit, not a student permit, to apply for the ministry grants and that special grants for foreign students must be applied for in the home country. UAB aid lines are enrolment grants, collaboration grants, Santander Excelencia 360, #UABRefugi, the equity grant and language-course grants, plus a mobility budget for UAB students going abroad.', 'https://www.uab.cat/web/mobility-international-exchange/mobility-international-exchange-programmes/faqs-para-estudiantes-internacionales-1345672012135.html'),
  (204, 'UAM Becas de Excelencia para Master Oficial', 'Yes', 'Merit-based tuition reimbursement', '100% of first-enrolment public fees, capped at 60 ECTS', true, '45 scholarships for students already enrolled and paid in an official UAM master''s degree. Minimum average 8.70 out of 10 (7.30 in Engineering and Architecture). Window 25 March to 15 September 2026. Incompatible with other tuition aid. The UAM Fondo Social requires Spanish or EU nationality.', 'https://www.uam.es/uam/estudios/beca-ayuda/uam-propias/becas-excelencia-master-26-27'),
  (196, 'UCM Matricula Aids for Grado and Master', 'Yes', 'Need-based tuition aid', '50% to 100% of enrolled credits, capped at EUR 2,100 for a master''s', true, 'Must be enrolled at a UCM centre. Window 25 February to 10 March 2026 through becas.ucm.es. Ranked competitively on family income and academic record. The UCM international master''s scholarships exempting up to 100% of tuition are restricted to AUIP Latin American graduates and are not open to applicants from Uzbekistan.', 'https://www.ucm.es/ayudas-ucm-de-matricula-para-grado-y-master'),
  (238, 'UC3M School of Graduate Studies Master''s Tuition Scholarships', 'Yes', 'Merit-based and need-aware tuition scholarship', 'A percentage of master''s tuition published inside each call', true, 'Open to any admitted master''s applicant: the general call AM01-26/27 ran from 1 December 2025 to 31 May 2026 and required the admission application and access fee to be paid by 31 May. Motivation letter plus declaration of other aid. The Madrid regional scholarship of EUR 2,100 requires a Madrid access examination or Bachillerato and is closed to applicants from Uzbekistan.', 'https://www.uc3m.es/postgraduate/scholarships/main/2026')
) AS v(id, name, avail, ftype, mx, tuition, elig, url)
WHERE u.id = v.id;
